'use client'

import { AnimatedNumber } from '@/registry/components/dashboardblocks/animated-number'
import { TinyLineChart } from '@/registry/components/dashboardblocks/chart'
import { KPIValue } from '@/registry/components/dashboardblocks/kpi'
import { Trend } from '@/registry/components/dashboardblocks/trend'
import { LineProps } from 'recharts'

import { Card, CardContent, CardDescription } from '@/components/ui/card'

interface LineChartKPIProps {
  change?: number
  data?: unknown[]
  height?: number
  lines?: LineProps[]
  title?: string
  trend?: 'up' | 'down' | 'neutral'
  value?: number
}

export const LineChartKPI1 = ({
  change = 4.2,
  data = [
    {
      label: 'Monday',
      value: 4200,
      displayValues: {
        value: '4.2k visits',
      },
    },
    {
      label: 'Tuesday',
      value: 5100,
      displayValues: {
        value: '5.1k visits',
      },
    },
    {
      label: 'Wednesday',
      value: 2800,
      displayValues: {
        value: '4.8k visits',
      },
    },
    {
      label: 'Thursday',
      value: 5600,
      displayValues: {
        value: '5.6k visits',
      },
    },
    {
      label: 'Friday',
      value: 6300,
      displayValues: {
        value: '6.3k visits',
      },
    },
    {
      label: 'Saturday',
      value: 5400,
      displayValues: {
        value: '5.4k visits',
      },
    },
    {
      label: 'Sunday',
      value: 6900,
      displayValues: {
        value: '4.9k visits',
      },
    },
  ],
  height = 120,
  lines = [
    {
      dataKey: 'value',
      stroke: 'var(--color-primary)',
    },
  ],
  title = 'Daily visitors',
  trend = 'up',
  value = 48230,
}: LineChartKPIProps) => {
  return (
    <Card>
      <CardContent>
        <div className='space-y-1'>
          <div className='flex items-center justify-between'>
            <CardDescription>{title}</CardDescription>
            <Trend
              value={
                <AnimatedNumber
                  value={change}
                  formatter={(value) => `${value.toLocaleString()}%`}
                />
              }
              trend={trend}
              variant='badge'
            />
          </div>
          <KPIValue>
            <AnimatedNumber value={value} formatter={(value) => value.toLocaleString()} />
          </KPIValue>
        </div>
        <TinyLineChart data={data} lines={lines} height={height} />
      </CardContent>
    </Card>
  )
}
